SET client_min_messages = warning;
SELECT 'T01'; SELECT extract(year FROM ts), extract(month FROM ts), extract(dow FROM ts), extract(doy FROM ts), extract(epoch FROM ts) FROM dc WHERE id=1;
SELECT 'T02'; SELECT extract(quarter FROM d), extract(week FROM d), extract(isodow FROM d), extract(century FROM d) FROM dc WHERE id=1;
SELECT 'T03'; SELECT date_trunc('day',ts), date_trunc('month',ts), date_trunc('year',ts), date_trunc('hour',ts) FROM dc WHERE id=1;
SELECT 'T04'; SELECT age(DATE '2020-03-01', DATE '2020-01-31'), age(DATE '2020-01-31', DATE '2020-03-01');
SELECT 'T05'; SELECT DATE '2020-01-31' + INTERVAL '1 month', DATE '2020-03-31' - INTERVAL '1 month';
SELECT 'T06'; SELECT DATE '2020-01-02' - DATE '2020-01-01', TIMESTAMP '2020-01-02' - TIMESTAMP '2020-01-01';
SELECT 'T07'; SELECT to_char(TIMESTAMP '2020-01-02 03:04:05','YYYY-MM-DD HH24:MI:SS'), to_char(DATE '2020-01-02','Day Mon');
SELECT 'T08'; SELECT to_char(INTERVAL '1 day 2 hours','HH24:MI'), to_char(TIMESTAMP '2020-01-02','Q W IYYY IW');
SELECT 'T09'; SELECT make_date(2020,1,2), make_time(3,4,5.5), make_interval(days=>1,hours=>2);
SELECT 'T10'; SELECT TIMESTAMP '2020-01-02 03:04:05' AT TIME ZONE 'UTC', TIMESTAMPTZ '2020-01-02 03:04:05+00' AT TIME ZONE 'Asia/Tokyo';
SELECT 'T11'; SELECT INTERVAL '1 day' + INTERVAL '2 hours', INTERVAL '1 day' * 2, INTERVAL '1 day' / 2;
SELECT 'T12'; SELECT date_part('year', INTERVAL '2 years 3 months'), extract(month FROM INTERVAL '14 months');
SELECT 'T13'; SELECT overlaps(DATE '2020-01-01', DATE '2020-02-01', DATE '2020-01-15', DATE '2020-03-01');
SELECT 'T14'; SELECT ts, d, tm, iv FROM dc ORDER BY id;
SELECT 'T15'; SELECT id, ts + INTERVAL '1 day', d + 1, tm + INTERVAL '1 hour' FROM dc WHERE id IN (1,4) ORDER BY id;
SELECT 'T16'; SELECT '2020-01-02'::DATE::TEXT, '03:04:05'::TIME::TEXT, '1 day'::INTERVAL::TEXT;
SELECT 'T17'; SELECT isfinite(DATE '2020-01-02'), isfinite(INTERVAL '1 day');
SELECT 'T18'; SELECT date_bin('1 hour', TIMESTAMP '2020-01-02 03:34:00', TIMESTAMP '2020-01-02 00:00:00');
